const { useEffect, useState } = React;

function Notice() {
  useEffect(() => {
    return () => {
      document.querySelector('#cleanup').textContent = '정리 완료';
    };
  }, []);
  return <p id="notice">알림 표시 중</p>;
}

function App() {
  const [visible, setVisible] = useState(true);
  return (
    <main>
      <button type="button" onClick={() => setVisible(false)}>알림 닫기</button>
      {visible && <Notice />}
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);
